Send Message.code:
// Send a prompt to Claude.
// The model's reply is written to state.data.
prompt(
  // 1) The message text. Reference upstream state with $.
  `Summarize this text: ${JSON.stringify($.data)}`,
  {
    // 2) Model id. Defaults to the latest Sonnet if omitted.
    model: 'claude-sonnet-4-6',
    // 3) Maximum tokens to generate in the reply.
    max_tokens: 1024,
    // 4) 0.0 = analytical / deterministic, 1.0 = creative.
    temperature: 0.7,
  }
);

Upload File.code:
// Not supported: this adaptor only exposes prompt() (the Messages API) and
// doesn't wrap Anthropic's Files API.
// Closest option: send the document inline with the prompt instead of
// uploading it first. Pass a base64-encoded PDF from an upstream step.
prompt(null, {
  messages: [
    {
      role: 'user',
      content: [
        {
          type: 'document',
          source: { type: 'base64', media_type: 'application/pdf', data: $.data.pdfBase64 },
        },
        { type: 'text', text: 'Summarise the key findings of this report.' },
      ],
    },
  ],
});

